42	function HeadlessCheck({ isHeadless }) {
43	  // When launched in background (isHeadless === true), render nothing until the
44	  // user actually opens the app. Without this, the process stays alive with a
45	  // blank React view, the LaunchScreen disappears and reveals nothing.
46	  const [active, setActive] = useState(!isHeadless);
47	
48	  useEffect(() => {
49	    if (!isHeadless) return;
50	    const sub = AppState.addEventListener("change", (state) => {
51	      if (state === "active") setActive(true);
52	    });
53	    return () => sub.remove();
54	  }, [isHeadless]);
55	
56	  if (!active) return null;
57	  return <App />;
58	}
59	
60	AppRegistry.registerComponent(appName, () => HeadlessCheck);
